return $input.all().map(item => {
  let rawResponse = item.json.raw_text
    || item.json.response
    || item.json.text
    || item.json.output
    || item.json.message?.content
    || '';

  const latency = item.json.latency_seconds || null;

  if (!rawResponse || typeof rawResponse !== 'string') {
    return {
      json: {
        success: false,
        clean_text: 'No advice returned.',
        response: 'No advice returned.',
        text: 'No advice returned.',
        tips: [],
        latency_seconds: latency
      }
    };
  }

  // --- Step 0: Handle stringified or truncated JSON / Model Hallucinations ---
  let t = rawResponse.trim();

  // If the model dumped raw JSON or a truncated JSON string
  if (t.startsWith('{') || t.startsWith('[')) {
    let parsedText = null;

    // Try normal JSON.parse first
    try {
      const parsed = JSON.parse(t);
      parsedText = parsed.reason 
        || parsed.instruction 
        || parsed.clean_text 
        || (Array.isArray(parsed) && parsed[0]?.reason)
        || (parsed.instance_info && parsed.instance_info[0]?.reason);
    } catch (_) {
      // If JSON is broken/truncated, extract "reason" or "instruction" via regex
      const matchReason = t.match(/"reason"\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"/i)
        || t.match(/"instruction"\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"/i);

      if (matchReason && matchReason[1]) {
        parsedText = matchReason[1].replace(/\\"/g, '"').replace(/\\n/g, '\n');
      }
    }

    if (parsedText) {
      t = parsedText;
    }
  }

  // 1. Remove code blocks and HTML tags
  t = t
    .replace(/```(?:json)?[\s\S]*?```/gi, '')
    .replace(/<[^>]+>/g, '');

  // 2. Remove markdown formatting and standardize punctuation
  t = t
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/\*([^*]+)\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    .replace(/_([^_]+)_/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/^#+\s*/gm, '')
    .replace(/^>\s*/gm, '')
    .replace(/[\u2014\u2013]/g, ' - ')
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/\\"/g, '"')
    .replace(/\r\n/g, '\n');

  // 3. Remove conversational intros / filler
  const introPatterns = [
    /^(?:sure|certainly|absolutely|of course|hello|hi|hey|ok|okay)[!.,\s]*/i,
    /^(?:here (?:is|are)|i have|below (?:is|are))\s+(?:\d+\s+)?(?:quick\s+)?(?:tips|recommendations|advice|suggestions|steps|rules)[^:\n]*[:\n\s]*/i,
    /^(?:based on (?:the|this) (?:image|photo|picture|scene)|looking at (?:the|this) (?:image|photo))[^:\n]*[:\n\s]*/i
  ];
  for (const pat of introPatterns) {
    t = t.replace(pat, '').trim();
  }

  // 4. Remove conversational outros / pleasantries
  const outroPatterns = [
    /(?:\n\s*|\.\s+)(?:these tips (?:can|will) help|hope this helps|hope (?:these|this)|let me know if|happy (?:shooting|clicking)|feel free to ask)[\s\S]*$/i,
    /(?:\n\s*|\.\s+)bonus(?: tip)?[:\s\S]*$/i
  ];
  for (const pat of outroPatterns) {
    t = t.replace(pat, '').trim();
  }

  // 5. Extract numbered or bulleted tips
  const tips = [];
  const pointRegex = /(?:^|\n)(?:(?:\d+|[A-Za-z])[\.\)]|[-•*])\s*([\s\S]*?)(?=(?:\n(?:(?:\d+|[A-Za-z])[\.\)]|[-•*])|\n\n|$))/g;
  let match;
  while ((match = pointRegex.exec(t)) !== null) {
    let pt = match[0].trim();
    pt = pt.replace(/^(?:(?:\d+|[A-Za-z])[\.\)]|[-•*])\s*/, '').trim();
    if (pt.length > 5 && !tips.includes(pt)) {
      tips.push(pt);
    }
  }

  // 6. Build clean text
  let cleanText = '';
  if (tips.length > 0) {
    cleanText = tips.map((tip, idx) => `${idx + 1}. ${tip}`).join('\n\n');
  } else {
    cleanText = t.replace(/\n{3,}/g, '\n\n').trim();
  }

  // Check if we ended up with valid advice or an unparsed loop
  const isValid = cleanText.length > 0 && !cleanText.startsWith('{"');

  return {
    json: {
      success: isValid,
      clean_text: isValid ? cleanText : 'Unable to parse valid advice.',
      response: isValid ? cleanText : 'Unable to parse valid advice.',
      text: isValid ? cleanText : 'Unable to parse valid advice.',
      tips: tips.length > 0 ? tips : (isValid ? [cleanText] : []),
      latency_seconds: latency
    }
  };
});

